<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
function all(PDO $db,string $sql,array $args=[]): array {$s=$db->prepare($sql);$s->execute($args);return $s->fetchAll();}
function one(PDO $db,string $sql,array $args=[]): array|false {$s=$db->prepare($sql);$s->execute($args);return $s->fetch();}
function audit(PDO $db,int $uid,string $event,?int $id=null): void {$s=$db->prepare('INSERT INTO audit_log(user_id,event_type,record_id) VALUES (?,?,?)');$s->execute([$uid,$event,$id]);}
function fmt(mixed $n): string{return number_format((float)$n,2,'.',',');}
$page=(string)($_GET['page']??'dashboard');
if(!in_array($page,['login','dashboard','entries','accounts','budgets','reports','settings','team'],true))$page='dashboard';
$month=isset($_GET['month'])?trim((string)$_GET['month']):date('Y-m');
try{$month=Finance::month($month);}catch(Throwable){$month=date('Y-m');}
$error='';$db=null;
try{
 if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
  verify_csrf();$action=(string)($_POST['action']??'');
  if($action==='login'){
   $db=Database::connection();if(!login($db,post_string('email',190),(string)($_POST['password']??'')))throw new DomainException('Invalid credentials.');
   redirect('dashboard','Signed in.');
  }
  $u=require_user();$uid=(int)$u['id'];$db=Database::connection();
  if($action==='logout'){logout();header('Location: ?page=login',true,303);exit;}
  if($action==='entry'){
   require_role(['admin','accountant']);$date=post_string('entry_date',10);$m=Finance::periodFromDate($date);
   $kind=post_string('kind',12);$account=(int)($_POST['account_id']??0);$category=(int)($_POST['category_id']??0);
   $amount=Finance::money($_POST['amount']??'');$description=post_string('description',255);$ref=post_string('reference_no',90);
   if(!in_array($kind,['income','expense'],true)||$account<1||$category<1||$amount<=0||$description==='')throw new DomainException('Invalid income/expense record.');
   $db->beginTransaction();try{
    Finance::ensureUnlocked($db,$m);
    $c=one($db,'SELECT kind FROM categories WHERE id=?',[$category]);$a=one($db,'SELECT id FROM accounts WHERE id=? AND active=1',[$account]);
    if(!$c||$c['kind']!==$kind||!$a)throw new DomainException('Choose an active account and matching category.');
    $s=$db->prepare('INSERT INTO transactions(entry_date,kind,account_id,category_id,amount,description,reference_no,created_by) VALUES (?,?,?,?,?,?,?,?)');
    $s->execute([$date,$kind,$account,$category,$amount,$description,$ref,$uid]);audit($db,$uid,'ledger.entry.created',(int)$db->lastInsertId());
    $db->commit();redirect('entries','Ledger entry posted.');
   }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
  }
  if($action==='transfer'){
   require_role(['admin','accountant']);$date=post_string('transfer_date',10);$m=Finance::periodFromDate($date);
   $from=(int)($_POST['source_account_id']??0);$to=(int)($_POST['target_account_id']??0);$amount=Finance::money($_POST['amount']??'');
   if($from<1||$to<1||$from===$to||$amount<=0)throw new DomainException('Choose two different accounts and a positive amount.');
   $db->beginTransaction();try{
    Finance::ensureUnlocked($db,$m);
    $ids=all($db,'SELECT id FROM accounts WHERE id IN (?,?) AND active=1 ORDER BY id FOR UPDATE',[$from,$to]);
    if(count($ids)!==2)throw new DomainException('Both accounts must exist and be active.');
    if(Finance::accountBalance($db,$from)<$amount)throw new DomainException('Insufficient source account balance.');
    $s=$db->prepare('INSERT INTO transfers(transfer_date,source_account_id,target_account_id,amount,reference_no,created_by) VALUES(?,?,?,?,?,?)');
    $s->execute([$date,$from,$to,$amount,post_string('reference_no',90),$uid]);audit($db,$uid,'account.transfer.created',(int)$db->lastInsertId());
    $db->commit();redirect('accounts','Transfer recorded atomically.');
   }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
  }
  if($action==='account'){
   require_role(['admin']);$code=post_string('code',40);$name=post_string('name',160);$opening=Finance::money($_POST['opening_balance']??'0');
   if($code===''||$name==='')throw new DomainException('Account code and name required.');
   $s=$db->prepare('INSERT INTO accounts(code,name,opening_balance) VALUES (?,?,?)');$s->execute([$code,$name,$opening]);audit($db,$uid,'account.created',(int)$db->lastInsertId());redirect('accounts','Account created.');
  }
  if($action==='category'){
   require_role(['admin']);$name=post_string('name',160);$kind=post_string('kind',12);
   if($name===''||!in_array($kind,['income','expense'],true))throw new DomainException('Invalid category.');
   $s=$db->prepare('INSERT INTO categories(name,kind) VALUES (?,?)');$s->execute([$name,$kind]);audit($db,$uid,'category.created',(int)$db->lastInsertId());redirect('settings','Category created.');
  }
  if($action==='budget'){
   require_role(['admin','accountant']);$m=Finance::month(post_string('month',7));$cat=(int)($_POST['category_id']??0);$amount=Finance::money($_POST['planned_amount']??'');
   $db->beginTransaction();try{
    Finance::ensureUnlocked($db,$m);
    $c=one($db,"SELECT id FROM categories WHERE id=? AND kind='expense'",[$cat]);if(!$c)throw new DomainException('Select an expense category.');
    $s=$db->prepare('INSERT INTO budgets(month,category_id,planned_amount) VALUES(?,?,?) ON DUPLICATE KEY UPDATE planned_amount=VALUES(planned_amount)');
    $s->execute([$m,$cat,$amount]);audit($db,$uid,'budget.updated',$cat);$db->commit();redirect('budgets','Budget saved.');
   }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
  }
  if($action==='period_lock'){
   require_role(['admin']);$m=Finance::month(post_string('month',7));$locked=(int)($_POST['locked']??1)?1:0;
   $db->beginTransaction();try{
    $s=$db->prepare('INSERT INTO periods(month,is_locked,updated_by,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE is_locked=VALUES(is_locked),updated_by=VALUES(updated_by),updated_at=NOW()');
    $s->execute([$m,$locked,$uid]);audit($db,$uid,$locked?'period.locked':'period.unlocked');$db->commit();redirect('reports','Period lock updated.');
   }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
  }
  if($action==='settings'){
   require_role(['admin']);$name=post_string('company_name',190);$currency=strtoupper(post_string('currency_code',3));
   if($name===''||!preg_match('/^[A-Z]{3}$/D',$currency))throw new DomainException('Invalid settings.');
   $s=$db->prepare('UPDATE settings SET company_name=?,currency_code=? WHERE id=1');$s->execute([$name,$currency]);audit($db,$uid,'settings.updated');redirect('settings','Settings updated.');
  }
  if($action==='add_user'){
   require_role(['admin']);$name=post_string('name',120);$email=post_string('email',190);$password=(string)($_POST['password']??'');$role=post_string('role',20);
   if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12||!in_array($role,['admin','accountant','viewer'],true))throw new DomainException('Invalid account details. Password: 12+ characters.');
   $s=$db->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);audit($db,$uid,'user.created',(int)$db->lastInsertId());redirect('team','Team account created.');
  }
  throw new DomainException('Unknown action.');
 }
}catch(Throwable $e){$error=$e->getMessage();}
if($page==='login'||!current_user())$page='login';
if($page!=='login'&&$db===null){try{$db=Database::connection();}catch(Throwable $e){$error=$e->getMessage();}}
$u=current_user();$settings=$u&&$db?one($db,'SELECT * FROM settings WHERE id=1'):null;
$accounts=$u&&$db?all($db,'SELECT a.*, a.opening_balance + COALESCE((SELECT SUM(CASE WHEN kind="income" THEN amount ELSE -amount END) FROM transactions WHERE account_id=a.id),0) + COALESCE((SELECT SUM(amount) FROM transfers WHERE target_account_id=a.id),0) - COALESCE((SELECT SUM(amount) FROM transfers WHERE source_account_id=a.id),0) AS balance FROM accounts a ORDER BY a.code'):[];
$categories=$u&&$db?all($db,'SELECT * FROM categories ORDER BY kind,name'):[];
$tx=$u&&$db?all($db,'SELECT t.*,a.name AS account_name,c.name AS category_name FROM transactions t JOIN accounts a ON a.id=t.account_id JOIN categories c ON c.id=t.category_id WHERE t.entry_date>=? AND t.entry_date<? ORDER BY t.entry_date DESC,t.id DESC LIMIT 300',[$month.'-01',date('Y-m-d',strtotime($month.'-01 +1 month'))]):[];
$budgets=$u&&$db?all($db,"SELECT c.id AS category_id,c.name,b.planned_amount,COALESCE(SUM(t.amount),0) AS actual FROM categories c LEFT JOIN budgets b ON b.category_id=c.id AND b.month=? LEFT JOIN transactions t ON t.category_id=c.id AND t.kind='expense' AND t.entry_date>=? AND t.entry_date<? WHERE c.kind='expense' GROUP BY c.id,c.name,b.planned_amount ORDER BY c.name",[$month,$month.'-01',date('Y-m-d',strtotime($month.'-01 +1 month'))]):[];
$totals=$u&&$db?one($db,"SELECT COALESCE(SUM(CASE WHEN kind='income' THEN amount ELSE 0 END),0) AS income,COALESCE(SUM(CASE WHEN kind='expense' THEN amount ELSE 0 END),0) AS expense FROM transactions WHERE entry_date>=? AND entry_date<?",[$month.'-01',date('Y-m-d',strtotime($month.'-01 +1 month'))]):['income'=>0,'expense'=>0];
$income=(float)($totals['income']??0);$expense=(float)($totals['expense']??0);$currency=$settings['currency_code']??'AOA';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>BusinessFinance 360 · Open Source</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><style>
:root{color-scheme:dark}body{background:#0b1423;color:#e9eefc;font-family:system-ui,-apple-system,'Segoe UI',sans-serif}.navbar,.panel{background:#17233a;border:1px solid #2b3955}.panel{border-radius:16px;padding:1.25rem}.nav-link,.text-secondary{color:#b0bbd5!important}.table{--bs-table-bg:transparent;--bs-table-color:#e8efff;--bs-table-border-color:#3b4b62}.form-control,.form-select{background:#111b30;border-color:#425374;color:#fff}.form-control:focus,.form-select:focus{background:#111b30;color:#fff}.btn-primary{background:#146d87;border-color:#146d87}.kpi{font-size:1.8rem;font-weight:800}.muted{color:#b0bbd5}.footer{font-size:.85rem;color:#b1bfd6}.footer a{color:#8cdeed}.bar{height:8px;background:#26344b;border-radius:50px;overflow:hidden}.bar span{display:block;height:100%;background:#21b5a8}.smallcap{letter-spacing:.11em;font-size:.76rem;text-transform:uppercase}</style></head><body>
<nav class="navbar navbar-expand-lg navbar-dark"><div class="container"><a href="?page=dashboard" class="navbar-brand fw-bold">◉ BusinessFinance 360</a><?php if($u):?><div class="d-flex flex-wrap align-items-center gap-3"><a class="nav-link" href="?page=dashboard">Dashboard</a><a class="nav-link" href="?page=entries">Ledger</a><a class="nav-link" href="?page=accounts">Accounts</a><a class="nav-link" href="?page=budgets">Budgets</a><a class="nav-link" href="?page=reports">Reports</a><a class="nav-link" href="?page=settings">Settings</a><?php if($u['role']==='admin'):?><a class="nav-link" href="?page=team">Team</a><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="logout"><button class="btn btn-outline-light btn-sm">Sign out</button></form></div><?php endif;?></div></nav>
<main class="container py-4" style="min-height:80vh"><div class="smallcap muted">Santos António Open Source · Business operations</div><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><h1 class="fw-bold mt-2"><?=e(match($page){'login'=>'Company sign in','entries'=>'Income and expense ledger','accounts'=>'Cash and bank accounts','budgets'=>'Monthly budgets','reports'=>'Management reporting','settings'=>'Business setup','team'=>'Users and roles',default=>'Financial dashboard'})?></h1><p class="muted mb-0">Internal management reporting · Not certified statutory accounting or electronic invoicing.</p></div><?php if($u):?><form method="get" class="d-flex gap-2"><input type="hidden" name="page" value="<?=e($page)?>"><input type="month" name="month" class="form-control" value="<?=e($month)?>"><button class="btn btn-outline-light">View</button></form><?php endif;?></div>
<?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(!empty($_SESSION['flash'])):?><div class="alert alert-success"><?=e($_SESSION['flash'])?></div><?php unset($_SESSION['flash']);endif;?>
<?php if($page==='login'):?><div class="row justify-content-center"><div class="col-md-5"><div class="panel"><h2 class="h4">Secure sign in</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="login"><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Password</label><input class="form-control mb-4" type="password" name="password" required><button class="btn btn-primary w-100">Sign in</button></form><p class="small muted mt-3">Bootstrap administrator via the CLI creation script after database import.</p></div></div></div>
<?php elseif($page==='dashboard'):?>
<div class="row g-3 mb-4"><div class="col-md-4"><div class="panel"><div class="muted">Monthly income · <?=e($currency)?></div><div class="kpi text-success"><?=fmt($income)?></div></div></div><div class="col-md-4"><div class="panel"><div class="muted">Monthly expenses · <?=e($currency)?></div><div class="kpi text-warning"><?=fmt($expense)?></div></div></div><div class="col-md-4"><div class="panel"><div class="muted">Management surplus / deficit</div><div class="kpi"><?=fmt($income-$expense)?></div></div></div></div>
<div class="row g-4"><div class="col-lg-6"><div class="panel"><h2 class="h5">Bank and cash balances</h2><table class="table"><thead><tr><th>Account</th><th>Balance · <?=e($currency)?></th></tr></thead><tbody><?php foreach($accounts as $a):?><tr><td><?=e($a['code'])?> · <?=e($a['name'])?></td><td><?=fmt($a['balance'])?></td></tr><?php endforeach;?></tbody></table><p class="small muted">Balances include opening figures, ledger entries and internal transfers. They do not constitute a bank reconciliation.</p></div></div><div class="col-lg-6"><div class="panel"><h2 class="h5">Expense budget vs actual</h2><?php foreach($budgets as $b): $limit=(float)($b['planned_amount']??0);$actual=(float)$b['actual'];?><div class="d-flex justify-content-between small mb-1"><span><?=e($b['name'])?></span><span><?=fmt($actual)?> / <?=fmt($limit)?></span></div><div class="bar mb-3"><span style="width:<?=($limit>0?min(100,round(100*$actual/$limit,1)):0)?>%"></span></div><?php endforeach;?></div></div></div>
<?php elseif($page==='entries'):?>
<?php if(in_array($u['role'],['admin','accountant'],true)):?><div class="panel mb-4"><h2 class="h5">Post a new cashflow entry</h2><form class="row g-2" method="post"><?=csrf_field()?><input type="hidden" name="action" value="entry"><div class="col-md-2"><label class="form-label">Date</label><input class="form-control" type="date" name="entry_date" value="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><label class="form-label">Type</label><select class="form-select" name="kind" id="entrykind"><option value="income">Income</option><option value="expense">Expense</option></select></div><div class="col-md-2"><label class="form-label">Account</label><select class="form-select" name="account_id" required><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Category</label><select class="form-select" name="category_id" required><?php foreach($categories as $c):?><option data-kind="<?=e($c['kind'])?>" value="<?=(int)$c['id']?>"><?=e($c['kind'])?> · <?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Amount</label><input class="form-control" name="amount" type="number" min="0.01" step="0.01" required></div><div class="col-md-2"><label class="form-label">Reference</label><input class="form-control" name="reference_no"></div><div class="col-md-10"><label class="form-label">Description</label><input class="form-control" name="description" required></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Post entry</button></div></form></div><?php endif;?>
<div class="panel"><h2 class="h5">Ledger · <?=e($month)?></h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Date</th><th>Type</th><th>Account</th><th>Category</th><th>Reference</th><th>Description</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach($tx as $r):?><tr><td><?=e($r['entry_date'])?></td><td><?=e($r['kind'])?></td><td><?=e($r['account_name'])?></td><td><?=e($r['category_name'])?></td><td><?=e($r['reference_no'])?></td><td><?=e($r['description'])?></td><td class="text-end"><?=fmt($r['amount'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php elseif($page==='accounts'):?>
<div class="row g-4"><div class="col-lg-7"><div class="panel"><h2 class="h5">Cash / bank accounts</h2><table class="table"><thead><tr><th>Code</th><th>Name</th><th>Opening</th><th>Current balance</th></tr></thead><tbody><?php foreach($accounts as $a):?><tr><td><?=e($a['code'])?></td><td><?=e($a['name'])?></td><td><?=fmt($a['opening_balance'])?></td><td><?=fmt($a['balance'])?></td></tr><?php endforeach;?></tbody></table></div></div><div class="col-lg-5"><div class="panel mb-4"><h2 class="h5">Transfer between accounts</h2><?php if(in_array($u['role'],['admin','accountant'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="transfer"><label class="form-label">Date</label><input type="date" class="form-control mb-2" name="transfer_date" value="<?=date('Y-m-d')?>" required><label class="form-label">Source</label><select class="form-select mb-2" name="source_account_id"><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select><label class="form-label">Destination</label><select class="form-select mb-2" name="target_account_id"><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select><label class="form-label">Amount</label><input type="number" min="0.01" step=".01" class="form-control mb-2" name="amount" required><label class="form-label">Reference</label><input name="reference_no" class="form-control mb-3"><button class="btn btn-primary">Post transfer</button></form><?php endif;?></div>
<?php if($u['role']==='admin'):?><div class="panel"><h2 class="h5">New account</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="account"><label class="form-label">Code</label><input class="form-control mb-2" name="code" required><label class="form-label">Name</label><input class="form-control mb-2" name="name" required><label class="form-label">Opening balance</label><input class="form-control mb-3" name="opening_balance" type="number" min="0" step=".01" value="0"><button class="btn btn-outline-light">Create account</button></form></div><?php endif;?></div></div>
<?php elseif($page==='budgets'):?>
<div class="row g-4"><div class="col-lg-7"><div class="panel"><h2 class="h5">Planned and actual expenses · <?=e($month)?></h2><table class="table"><thead><tr><th>Category</th><th>Budget</th><th>Actual</th><th>Variance</th></tr></thead><tbody><?php foreach($budgets as $b):?><tr><td><?=e($b['name'])?></td><td><?=fmt($b['planned_amount'])?></td><td><?=fmt($b['actual'])?></td><td><?=fmt((float)$b['planned_amount']-(float)$b['actual'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php if(in_array($u['role'],['admin','accountant'],true)):?><div class="col-lg-5"><div class="panel"><h2 class="h5">Set monthly budget</h2><form method="post"><?=csrf_field()?><input name="action" type="hidden" value="budget"><label class="form-label">Month</label><input name="month" type="month" value="<?=e($month)?>" class="form-control mb-2"><label class="form-label">Expense category</label><select name="category_id" class="form-select mb-2"><?php foreach($categories as $c):if($c['kind']==='expense'):?><option value="<?=(int)$c['id']?>"><?=e($c['name'])?></option><?php endif;endforeach;?></select><label class="form-label">Budgeted amount</label><input name="planned_amount" type="number" min="0" step=".01" class="form-control mb-3" required><button class="btn btn-primary">Save budget</button></form></div></div><?php endif;?></div>
<?php elseif($page==='reports'):?>
<div class="row g-4"><div class="col-lg-8"><div class="panel"><h2 class="h5">Month <?=e($month)?> · export</h2><p class="muted">Income: <?=fmt($income)?> · Expenses: <?=fmt($expense)?> · Net: <?=fmt($income-$expense)?> <?=e($currency)?></p><a class="btn btn-primary" href="export.php?month=<?=urlencode($month)?>&type=transactions">Download ledger CSV</a> <a class="btn btn-outline-light" href="export.php?month=<?=urlencode($month)?>&type=budget">Download budget CSV</a></div></div><?php if($u['role']==='admin'):?><div class="col-lg-4"><div class="panel"><h2 class="h5">Close or reopen month</h2><p class="small muted">Locking prevents new backdated entries, transfers and budget changes for this month.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="period_lock"><input type="month" name="month" class="form-control mb-2" value="<?=e($month)?>" required><select class="form-select mb-3" name="locked"><option value="1">Close / lock</option><option value="0">Reopen</option></select><button class="btn btn-warning">Update period</button></form></div></div><?php endif;?></div>
<?php elseif($page==='settings'):?>
<div class="row g-4"><div class="col-lg-5"><div class="panel"><h2 class="h5">Business details</h2><?php if($u['role']==='admin'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="settings"><label class="form-label">Company</label><input class="form-control mb-2" name="company_name" value="<?=e($settings['company_name']??'')?>" required><label class="form-label">Currency (ISO 4217)</label><input class="form-control mb-3" maxlength="3" name="currency_code" value="<?=e($currency)?>" required><button class="btn btn-primary">Save</button></form><?php else:?><p><?=e($settings['company_name']??'')?> · <?=e($currency)?></p><?php endif;?></div></div><div class="col-lg-7"><div class="panel"><h2 class="h5">Income and expense categories</h2><table class="table"><thead><tr><th>Category</th><th>Type</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['kind'])?></td></tr><?php endforeach;?></tbody></table><?php if($u['role']==='admin'):?><form method="post" class="row g-2"><?=csrf_field()?><input name="action" type="hidden" value="category"><div class="col-md-6"><input name="name" class="form-control" placeholder="New category" required></div><div class="col-md-4"><select class="form-select" name="kind"><option value="expense">Expense</option><option value="income">Income</option></select></div><div class="col-md-2"><button class="btn btn-outline-light">Add</button></div></form><?php endif;?></div></div></div>
<?php elseif($page==='team'&&$u['role']==='admin'):?>
