<script>const k=document.getElementById('entrykind');const s=document.querySelector('[name="category_id"]');if(k&&s){function change(){for(const option of s.options){option.hidden=option.dataset.kind!==k.value;option.disabled=option.hidden;}const allowed=[...s.options].find(x=>!x.disabled);if(allowed)s.value=allowed.value;}k.addEventListener('change',change);change();}</script></body></html>
